import React, { useState } from 'react';
import { Card, Button, Form, Row, Col, Badge } from 'react-bootstrap';

const Settings = () => {
  const [theme, setTheme] = useState(
    document.documentElement.getAttribute('data-theme') || 'light'
  );

  const toggleTheme = () => {
    const nextTheme = theme === 'dark' ? 'light' : 'dark';
    document.documentElement.setAttribute('data-theme', nextTheme);
    setTheme(nextTheme);
  };

  return (
    <div>
      <div className="mb-4">
        <h3 className="fw-bold mb-1">System & Appearance Settings</h3>
        <p className="text-muted small mb-0">Configure dashboard preferences, theme modes, and API connections.</p>
      </div>

      <Row className="g-4">
        <Col md={6}>
          <Card className="p-4 border-0">
            <h5 className="fw-bold mb-2">Theme Mode</h5>
            <p className="text-muted small mb-4">Toggle between Light and Dark themes across the entire CRM panel.</p>
            <div className="d-flex align-items-center justify-content-between p-3 rounded-3 mb-3" style={{ background: 'var(--bg-primary)' }}>
              <div>
                <div className="fw-semibold">Current Active Theme</div>
                <div className="small text-capitalize text-muted">{theme} Mode</div>
              </div>
              <Button variant={theme === 'dark' ? 'light' : 'dark'} onClick={toggleTheme} style={{ borderRadius: '10px' }}>
                Switch to {theme === 'dark' ? 'Light' : 'Dark'} Mode
              </Button>
            </div>
          </Card>
        </Col>

        <Col md={6}>
          <Card className="p-4 border-0">
            <h5 className="fw-bold mb-2">System Connections</h5>
            <p className="text-muted small mb-3">Backend API and WebSockets server status</p>
            <Form.Group className="mb-3">
              <Form.Label className="small fw-semibold">Backend API Endpoint</Form.Label>
              <Form.Control type="text" value="http://localhost:5000/api" readOnly style={{ borderRadius: '10px' }} />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Label className="small fw-semibold">WebSocket Connection</Form.Label>
              <div>
                <Badge bg="success" className="px-3 py-2 rounded-pill">Connected to ws://localhost:5000</Badge>
              </div>
            </Form.Group>
          </Card>
        </Col>
      </Row>
    </div>
  );
};

export default Settings;
